// One editable PowerPoint slide. Data are generated by collect_evidence.py.
// RUNTIME_ROOT and PRESENTATIONS_SKILL may override the bundled Windows paths.
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';
const here=path.dirname(fileURLToPath(import.meta.url)),workspace=path.dirname(here);
const runtime=process.env.RUNTIME_ROOT??path.join(os.homedir(),'.cache/codex-runtimes/codex-primary-runtime/dependencies');
const skill=process.env.PRESENTATIONS_SKILL??path.join(os.homedir(),'.codex/plugins/cache/openai-primary-runtime/presentations/26.909.12148/skills/presentations');
process.env.RUNTIME_NODE_MODULES=path.join(runtime,'node/node_modules');
process.env.RUNTIME_NODE=path.join(runtime,'node/bin/node.exe');
process.env.RUNTIME_PYTHON=path.join(runtime,'python/python.exe');
const {Presentation,PresentationFile,FileBlob}=await import(pathToFileURL(path.join(runtime,'node/node_modules/@oai/artifact-tool/dist/artifact_tool.mjs')));
const {finalizePresentation,applyPresentationChartFont}=await import(pathToFileURL(path.join(skill,'container_tools/artifact_tool_utils.mjs')));
const build=path.join(workspace,'.build'),output=path.join(workspace,'evidence/figures'),revision=Date.now();
await fs.mkdir(path.join(build,'release'),{recursive:true});await fs.mkdir(output,{recursive:true});
try {await fs.symlink(path.join(runtime,'node/node_modules'),path.join(build,'node_modules'),'junction');}
catch(e){if(e.code!=='EEXIST')throw e;}
const data=JSON.parse(await fs.readFile(path.join(workspace,'evidence/distribution.json'),'utf8'));
const s=data.summary,rows=data.requests,low=rows.filter(r=>r.reasoning_tokens<=s.threshold),high=rows.filter(r=>r.reasoning_tokens>s.threshold);
if(low.length+high.length!==s.n||high.length!==s.threshold_stats.above)throw new Error('Denominator mismatch');
const fmt=n=>n.toLocaleString('en-US'),pct=n=>(100*n/s.n).toFixed(2);
const F='Microsoft YaHei',C={ink:'#142C3D',muted:'#536B7C',gray:'#BCCBD3',teal:'#087F7C',gold:'#B16A16'};
const presentation=Presentation.create({slideSize:{width:1600,height:1000}}),slide=presentation.slides.add();
slide.background.fill='#FFFFFF';
function text(value,x,y,w,h,size=28,color=C.ink,bold=false){
 const t=slide.shapes.add({geometry:'textbox',name:value.slice(0,40),position:{left:x,top:y,width:w,height:h},fill:'none',line:{fill:'none',width:0}});
 t.text=value;t.text.style={typeface:F,fontSize:size,color,bold,autoFit:'none'};return t;
}
text('核心网运维 Agent 的 Vanilla 思考长度分布',70,40,1460,82,49,C.ink,true);
text(`Noemate 主 Agent：${fmt(s.n)} 条有效请求，${fmt(s.total_reasoning_tokens)} 个可见思考 token`,74,130,1450,48,27,C.muted);
text('全部有效请求：按实际到达时间展示',74,199,850,43,29,C.ink,true);
text('浅灰点：≤750    金色点：>750    金线：介入参考',920,207,650,35,22,C.muted);
const axes={textStyle:{typeface:F,fontSize:21,fill:C.muted},line:{fill:'#CDD8DE',width:1}};
const series=[
 {name:`≤750 token（${low.length}条）`,xValues:low.map(r=>Number(r.hours_from_start.toFixed(8))),values:low.map(r=>r.reasoning_tokens),fill:C.gray,line:{fill:'none',width:0},marker:{symbol:'circle',size:3}},
 {name:`>750 token（${high.length}条）`,xValues:high.map(r=>Number(r.hours_from_start.toFixed(8))),values:high.map(r=>r.reasoning_tokens),fill:C.gold,line:{fill:'none',width:0},marker:{symbol:'circle',size:5}},
 {name:'750 token 介入参考线',xValues:[0,12.15],values:[750,750],line:{fill:C.gold,width:2},marker:{symbol:'none'}}
];
const chart=slide.charts.add('scatter',{position:{left:70,top:273,width:1460,height:520},series,
 scatterOptions:{style:'lineWithMarkers'},hasLegend:false,
 xAxis:{...axes,min:0,max:12.15,majorUnit:2,numberFormatCode:'0',majorGridlines:null},
 yAxis:{...axes,min:0,max:2000,majorUnit:500,numberFormatCode:'#,##0',majorGridlines:{fill:'#EDF1F4',width:1}},
 dataLabels:{showValue:false,textStyle:{typeface:F,fontSize:20}},chartFill:'#FFFFFF',plotAreaFill:'#FFFFFF'});
applyPresentationChartFont(chart,{fontFamily:F});
text('可见思考长度 / token',78,247,760,33,21,C.muted);
text('距首请求的小时数（北京时间 09/17 20:37:51 起，每点一条请求）',160,795,1350,44,25,C.muted);
text(`${fmt(low.length)} 条（${pct(low.length)}%）≤750`,80,850,745,53,36,C.teal,true);
text(`${fmt(high.length)} 条（${pct(high.length)}%）>750`,885,850,640,53,36,C.gold,true);
text(`P50 / P95 / P99：${fmt(s.p50)} / ${fmt(s.p95)} / ${fmt(s.p99)} token；最大 ${fmt(s.max)}`,80,910,1440,34,23,C.muted);
text('baseline采集标记；主请求排除29条，辅助3,908条另列。多数请求总输出上限2048；分布不代表压缩收益或阈值安全性。',80,960,1450,31,18,C.muted);
slide.speakerNotes.textFrame.setText([
 '来源：docs/report/dtb_closeout/evidence/distribution.json、tables/vanilla_distribution.csv、source_manifest.json；来源SHA由生成脚本记录。',
 'capture agent_20260917T123724Z_7bac2ba7；主Agent8306，总请求12214。有效8277，主排除29（12 length、16 reasoning unknown、1 parse error）；推荐3897、压缩11不纳入思考分布。',
 '阈值采用本轮direct750实验介入候选，而非旧图850。严格>750有415条，恰好750有1条归≤750。达到阈值且仍在思考才可能接管；分布覆盖不等同实际旁路率。',
 'P95/P99按nearest rank计算，与原capture报告一致。横轴为UTC started_at差值（小时），PPT内嵌数据舍入至8位小数以符合Excel数值精度，原始时间完整保留在CSV，不强行建立session归属。',
 '模型请求名qwen3.6-27b，实际权重及服务native开关缺证。Vanilla沿用上传baseline标签。绝大多数max_tokens=2048，不能推广为无输出上限的分布。',
 '设计参考：docs/report/sum0911/统计图/思考长度长尾与850阈值.png。保留时间散点、阈值颜色和计数，移除右侧长尾拆解。当前范围0–2000，单一线性纵轴。',
 '原生scatter图保留全部8277点及内嵌XLSX，可用PowerPoint编辑数据。无截图替代图表。'
].join('\n'));
const common={workspaceDir:workspace,pythonExecutable:process.env.RUNTIME_PYTHON,
 integrityValidatorPath:path.join(skill,'container_tools/inspect_presentation_package_integrity.py'),
 layoutValidatorPath:path.join(skill,'container_tools/inspect_presentation_layout_geometry.py'),
 layoutArgs:['--expected-slide-size-emu','15240000,9525000','--validate-bullet-geometry','--validate-heading-fit'],
 explicitTotalSlideCount:1,requiredNativeChartOwnerSlides:[1],requiredNativeTableOwnerSlides:[],
 fontPolicy:{basis:'design',families:[F]},verifyArtifactToolImport:true};
const draft=path.join(build,`draft-${revision}.pptx`),materialized=path.join(build,'release',`data-${revision}.pptx`),repaired=path.join(build,`markers-${revision}.pptx`),final=path.join(build,'release',`final-${revision}.pptx`);
await(await PresentationFile.exportPptx(presentation)).save(draft);
await finalizePresentation({...common,candidatePath:draft,finalPath:materialized,materializeLiteralChartWorkbooks:true,receiptPath:path.join(build,`data-${revision}.json`)});
await promisify(execFile)(process.env.RUNTIME_PYTHON,[path.join(here,'repair_scatter.py'),materialized,repaired],{windowsHide:true,stdio:'ignore'});
await finalizePresentation({...common,candidatePath:repaired,finalPath:final,materializeLiteralChartWorkbooks:false,receiptPath:path.join(build,`validation-${revision}.json`)});
const destination=path.join(output,'vanilla_distribution.pptx');await fs.copyFile(final,destination);
// Preview rendering is opt-in: this runtime's PNG renderer finishes the file
// but faults during native shutdown on Windows (0xc0000409). PPT export and its
// independent validators do not have that shutdown fault.
if(process.argv.includes('--render-preview')){
 const imported=await PresentationFile.importPptx(await FileBlob.load(destination));
 const png=await imported.export({slide:imported.slides.items[0],format:'png',scale:1.5});
 await fs.writeFile(path.join(output,'vanilla_distribution.png'),new Uint8Array(await png.arrayBuffer()));
}
console.log(JSON.stringify({output:destination,slides:1,points:rows.length,threshold:s.threshold}));
